let client = new bacnet.default({
    apduTimeout: 10000
});

client.on('error', (err) => {
    node.error('BACnet client error: ' + err.message);
});

node.on('close', function() {
    try {
        client.close();
    } catch (e) {}
    global.set('bacnetClient', null);
});


const schedules = flow.get('schedulesParameters');
const currentSchedule = schedules[msg.nbr];


const address = {
    address: currentSchedule.targetip + ":" + flow.get("portdest")
};


function writePropertyAsync(address, objectId, propertyId, value, options) {
    return new Promise((resolve, reject) => {
        try {
            client.writeProperty(
                address,
                objectId,
                propertyId,
                value,
                options,
                (err, value) => {
                    if (err) {
                        reject(err);
                    } else {
                        resolve(value);
                    }
                }
            );
        } catch (err) {
            reject(err);
        }
    });
}



let BACNetWeeklySchedulePayload = msg.payload;


await writePropertyAsync(
    address, 
    {
        type: bacnet.ObjectType.SCHEDULE,
        instance: Number(currentSchedule.scheduleid)
    },
    bacnet.PropertyIdentifier.WEEKLY_SCHEDULE,
    BACNetWeeklySchedulePayload, 
    {}

);
client.close();

flow.set('portdest', "47808");
flow.set('sourcePort',"48809");
